import os
import shutil
import defusedxml.minidom as minidom

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
DOC_XML = 'unpacked/word/document.xml'

print('unpacked contents:', sorted(os.listdir('unpacked')))

if not os.path.exists('quarterly_report.backup.docx'):
    shutil.copy2('quarterly_report.docx', 'quarterly_report.backup.docx')
    print('backup created: quarterly_report.backup.docx')

doc = minidom.parse(DOC_XML)
root = doc.documentElement
print('root:', root.nodeName)

def elem_children(parent):
    return [c for c in parent.childNodes if c.nodeType == c.ELEMENT_NODE]

def local(n):
    return n.nodeName.split(':')[-1]

def children(parent, name):
    return [c for c in elem_children(parent) if local(c) == name]

def style_of(p):
    for pPr in children(p, 'pPr'):
        for ps in children(pPr, 'pStyle'):
            return ps.getAttribute('w:val')
    return None

def text_of(p):
    return ''.join(t.firstChild.data for t in p.getElementsByTagNameNS(W, 't') if t.firstChild)

# OOXML CT_RPr ordering: elements that must appear AFTER w:u
AFTER_U = {'highlight', 'effect', 'bdr', 'shd', 'fitText', 'vertAlign',
           'rtl', 'cs', 'em', 'lang', 'eastAsianLayout', 'specVanish',
           'oMath', 'AlternateContent'}

def ensure_underline(rPr):
    for u in children(rPr, 'u'):
        u.setAttribute('w:val', 'single')
        return
    u = doc.createElement('w:u')
    u.setAttribute('w:val', 'single')
    kids = elem_children(rPr)
    pos = None
    for i, c in enumerate(kids):
        if local(c) in AFTER_U:
            pos = i
            break
    if pos is not None:
        rPr.insertBefore(u, kids[pos])
    else:
        rPr.appendChild(u)

def underline_runs(p):
    n = 0
    for r in p.getElementsByTagNameNS(W, 'r'):
        rPrs = children(r, 'rPr')
        if rPrs:
            ensure_underline(rPrs[0])
        else:
            rPr = doc.createElement('w:rPr')
            r.insertBefore(rPr, r.firstChild)
            ensure_underline(rPr)
        n += 1
    return n

def underline_paragraph_mark(p):
    pPrs = children(p, 'pPr')
    if pPrs:
        pPr = pPrs[0]
    else:
        pPr = doc.createElement('w:pPr')
        p.insertBefore(pPr, p.firstChild)
    rPrs = children(pPr, 'rPr')
    if rPrs:
        ensure_underline(rPrs[0])
    else:
        rPr = doc.createElement('w:rPr')
        sects = children(pPr, 'sectPr')
        if sects:
            pPr.insertBefore(rPr, sects[0])
        else:
            pPr.appendChild(rPr)
        ensure_underline(rPr)

styles = {}
headings = []
for p in root.getElementsByTagNameNS(W, 'p'):
    s = style_of(p)
    styles[s] = styles.get(s, 0) + 1
    if s and s.lower().startswith('heading'):
        headings.append(p)

print('styles:', styles)
print('heading paragraphs:', len(headings))

runs = 0
for p in headings:
    runs += underline_runs(p)
    underline_paragraph_mark(p)

with open(DOC_XML, 'w', encoding='utf-8') as f:
    doc.writexml(f, encoding='UTF-8', newl='')

print('runs underlined:', runs)
for p in headings:
    print('  heading:', text_of(p)[:80])

