import zipfile
import defusedxml.minidom as minidom

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'

with zipfile.ZipFile('quarterly_report.docx') as z:
    xml = z.read('word/document.xml')

doc = minidom.parseString(xml)
root = doc.documentElement

def elem_children(parent):
    return [c for c in parent.childNodes if c.nodeType == c.ELEMENT_NODE]

def local(n):
    return n.nodeName.split(':')[-1]

def children(parent, name):
    return [c for c in elem_children(parent) if local(c) == name]

def text_of(p):
    return ''.join(t.firstChild.data for t in p.getElementsByTagNameNS(W, 't') if t.firstChild)

def is_headline(p):
    t = text_of(p).strip()
    if not t:
        return False
    has_letter = any(ch.isalpha() for ch in t)
    return has_letter and t == t.upper()

def has_u(rPr):
    for u in children(rPr, 'u'):
        if u.getAttribute('w:val') == 'single':
            return True
    return False

headlines = [p for p in root.getElementsByTagNameNS(W, 'p') if is_headline(p)]
print('headline paragraphs found:', len(headlines))

all_ok = True
for p in headlines:
    runs = p.getElementsByTagNameNS(W, 'r')
    bad_runs = 0
    for r in runs:
        rPrs = children(r, 'rPr')
        ok = False
        if rPrs and has_u(rPrs[0]):
            ok = True
        if not ok:
            bad_runs += 1
    mark_ok = False
    for pPr in children(p, 'pPr'):
        for rPr in children(pPr, 'rPr'):
            if has_u(rPr):
                mark_ok = True
    status = 'OK' if bad_runs == 0 and mark_ok else f'FAIL(runs_missing={bad_runs}, mark={mark_ok})'
    if status != 'OK':
        all_ok = False
    print(f'  {text_of(p)!r}: runs={len(runs)} {status}')

print('RESULT:', 'ALL HEADLINES UNDERLINED' if all_ok else 'PROBLEMS FOUND')

