    for u in children(rPr, 'u'):
        if u.getAttribute('w:val') == 'single':
            return True
    return False

headlines = [p for p in root.getElementsByTagNameNS(W, 'p') if is_headline(p)]
print('headline paragraphs found:', len(headlines))

all_ok = True
for p in headlines:
    runs = p.getElementsByTagNameNS(W, 'r')
    bad_runs = 0
    for r in runs:
        rPrs = children(r, 'rPr')
        ok = False
        if rPrs and has_u(rPrs[0]):
            ok = True
        if not ok:
            bad_runs += 1
    mark_ok = False
    for pPr in children(p, 'pPr'):
        for rPr in children(pPr, 'rPr'):
            if has_u(rPr):
                mark_ok = True
    status = 'OK' if bad_runs == 0 and mark_ok else f'FAIL(runs_missing={bad_runs}, mark={mark_ok})'
    if status != 'OK':
        all_ok = False
    print(f'  {text_of(p)!r}: runs={len(runs)} {status}')

print('RESULT:', 'ALL HEADLINES UNDERLINED' if all_ok else 'PROBLEMS FOUND')
